"前面是「手术室」：院长说手术很成功，病人只是还没醒。": "この先は「手術室」：院長いわく手術は成功、患者はまだ目覚めていないだけ。",
"前面是「海底」：港口下面还有一座城，城门是一张嘴。": "この先は「海底」：港の下にはもうひとつの町があり、その門は口になっている。",
"前面是「知识古树」：古树记得森林里发生过的每一件事，它不想再记住别的了。": "この先は「知恵の古木」：古木は森で起きたことをすべて覚えている。もうこれ以上、何も覚えたくない。",
"前面是「精灵女王」：女王在月池边等了三百年。她说，你就是她等的那个人。": "この先は「エルフの女王」：女王は月の池のほとりで三百年待っていた。あなたこそ待っていた人だと言う。",
"前面是「马戏大棚」：大棚里的笑声从来没停过，只是再也没有观众。": "この先は「サーカステント」：テントの笑い声は一度も止んでいない。ただ、もう観客はいない。",
"前面没人挡": "前に立つ者がいない",
